#' Check meteo data input as required by the 3DCMCCFEM model
#'
#' \code{check_meteo_3DFEM} perform some basic test on the variables in the
#' input meteo file (e.g., generated by the function \code{make_meteo_EOBS}) to
#' ensure compatibility with \code{run_3DCMCCFEM}. The function can also try to
#' correct inconsistency
#'
#' @param file_meteo Character or data.frame: path to meteo.txt file or
#'   data.frame of meteo.txt file read with read.table.
#' @param correct Logical: correct any errors found? Default to TRUE.
#' @param impute Logical: impute missing value using tree-based algorithm
#'   (bagging, requires the packages caret and ipred)? Default to TRUE.
#' @param save Logical: save meteo file?. Only if file_meteo is a path to a
#'   file. If TRUE, meteo file is saved with the same name and same directory of
#'   file_meteo. Default to FALSE
#' @param plot Logical: plot meteo file with \code{plot_meteo_3DFEM}?. Default
#'   to FALSE.
#' @param ... additional argument passed to \code{plot_meteo_3DFEM} when
#'   \code{plot=TRUE}
#'
#' @details The function check for consistency with the columns name convention
#'   of the model, for NA, missing data, missing observation in the weather time
#'   series, anomalous values in precipitation and temperature relations (i.e.,
#'   Tmin<=Tmean<=Tmax). If \code{correct=TRUE} colnames and temperature are
#'   fixed according to model specifications. After all checks, if
#'   \code{plot=TRUE} the function \code{plot_meteo_3DFEM} is call.
#'
#' @return a data.frame with the corrected weather time series if
#'   \code{correct=TRUE}, invisible otherwise. If \code{plot=TRUE} the function
#'   return a ggplot object if \code{save_plot=FALSE}. If \code{save_plot=TRUE}
#'   the function save in \code{outdir} a png file with the name of the site in
#'   \code{meteo_path_file}
#'
#' @seealso \code{\link{make_meteo_EOBS}} and
#'   \code{\link{plot_meteo_3DFEM}}
#' @export
#'


check_meteo_3DFEM <- function(file_meteo,correct=TRUE,impute=TRUE,save=FALSE,plot=FALSE,...){

  # input check -------------------------------------------------------------

  stopifnot("correct must be logical"=check_log(correct),
            "impute must be logical"=check_log(impute),
            "save must be logical"=check_log(save),
            "plot must be logical"=check_log(plot))

  # read data -----------------------------------------------------------------

  if(is.character(file_meteo)){
    meteo <- as.data.frame(data.table::fread(file_meteo))
  }else if (is.data.frame(file_meteo)){
    meteo <- as.data.frame(file_meteo)
  }else stop("file_meteo is of the wrong class")

  # check colnames ----------------------------------------------------------
  ref_col <- c("Year","Month","n_days","Rg_f","Ta_f","Tmax","Tmin","RH_f","Ts_f","Precip","SWC", "LAI","ET","WS_f")
  if(ncol(meteo)!=length(ref_col)){
    stop("The meteo file must have ",length(ref_col)," columns (",paste(ref_col,collapse=", "),"), found ",ncol(meteo),": ",paste(colnames(meteo),collapse=", "))
  }
  if(!identical(colnames(meteo), ref_col)){
    wrong <- colnames(meteo)!=ref_col
    warning("There are some column(s) with wrong name. Check the names convention for the model.\n",
            paste0(colnames(meteo)[wrong]," (should be ",ref_col[wrong],")",collapse="\n"))
    if(correct){
      colnames(meteo) <- ref_col
    }else {stop("Please correct column names")}
  }

  # check for missing data --------------------------------------------------

  ref_seq <- min(meteo$Year,na.rm=TRUE):max(meteo$Year,na.rm=TRUE)
  missing_year <- ref_seq[!ref_seq %in% meteo$Year]
  if (length(missing_year) != 0){
    warning("there are missing year(s) in the sequence. Missing year(s) are: ",paste(missing_year,collapse=" "))
  }

  year_day <- as.data.frame(table(meteo$Year),stringsAsFactors = FALSE)
  year_day$Var1 <- as.numeric(year_day$Var1)
  year_day$ref <- ifelse(lubridate::leap_year(year_day$Var1),366,365)
  check <- year_day$Freq!=year_day$ref
  if(any(check)){
    warning("Year(s) ",paste(year_day$Var1[check],collapse=" ")," have wrong numbers of day: ",paste(year_day$Freq[check],collapse=" "),". Should be: ",paste(year_day$ref[check],collapse=" "))
  }

  month_day <- stats::aggregate(Month ~ Year, data = meteo, FUN = function(x) length(unique(x)))
  check <- month_day$Month!=12
  if(any(check)){
    warning("Year(s) ",paste(month_day$Year[check],collapse=" ")," have wrong numbers of months: ",paste(month_day$Month[check],collapse=" "),". Should be: 12")
  }

  if(sum(!stats::complete.cases(meteo))!=0)warning("row(s) ",paste0(which(!stats::complete.cases(meteo)),collapse=" ")," contain some missing data. Please check")

  # impute ------------------------------------------------------------------

  if (impute && anyNA(meteo)) {
    if (!requireNamespace("caret", quietly = TRUE)) {
      stop("Package 'caret' (and 'ipred') is needed to impute missing values. Install it or use impute = FALSE")
    }
    # Ts_f, SWC, LAI, ET and WS_f are not used as predictors
    pp <- caret::preProcess(meteo[, -c(9, 11:14)], method = "bagImpute")
    meteo <- stats::predict(pp, meteo)
  }

  # check data -------------------------------------------------------------

  rows <- function(x) paste(which(x), collapse = " ")
  if(any(meteo$Rg_f<0,na.rm=TRUE))warning("Solar radiation is negative for row(s): ",rows(meteo$Rg_f<0))
  if(any(meteo$RH_f<0,na.rm=TRUE))warning("Relative humidity is negative for row(s): ",rows(meteo$RH_f<0))
  if(any(meteo$RH_f>100,na.rm=TRUE))warning("Relative humidity is greater than 100 for row(s): ",rows(meteo$RH_f>100))
  if(any(meteo$Precip<0,na.rm=TRUE))warning("Precipitation is negative for row(s): ",rows(meteo$Precip<0))

  # check temperature relations ----------------------------------------------

  ind1 <- meteo$Tmin<=meteo$Ta_f
  ind2 <-  meteo$Ta_f<=meteo$Tmax
  ind <- ind1&ind2
  pr <- meteo$Precip<0.0001&meteo$Precip!=0
  pr1 <- meteo$Precip>200
  rg <- meteo$Rg_f>60
  tm <- meteo$Ta_f>50

  if(any(!ind,na.rm=TRUE)) warning("There are ",sum(!ind,na.rm=TRUE)," row(s) in which temperatures are wrong (Tmin <= Ta_f <= Tmax is not respected)!")
  if(any(pr,na.rm=TRUE)) warning("There are ",sum(pr,na.rm=TRUE)," row(s) in which precipitation is less than the precision of the model!")
  if(any(pr1,na.rm=TRUE)) warning("There are ",sum(pr1,na.rm=TRUE)," row(s) in which precipitation is greater than 200 mm/day! This could be strange")
  if(any(rg,na.rm=TRUE)) warning("There are ",sum(rg,na.rm=TRUE)," row(s) in which radiation is greater than 60 MJ m-2 day-1")
  if(any(tm,na.rm=TRUE)) warning("There are ",sum(tm,na.rm=TRUE)," row(s) in which mean temperature is greater than 50 degrees C")

  df <- meteo
  if(correct){
    fix <- function(x) !is.na(x) & x
    df[fix(!ind1),"Tmin"] <-  df[fix(!ind1),"Ta_f"]
    df[fix(!ind2),"Tmax"] <-  df[fix(!ind2),"Ta_f"]

    na.mean <- function(x) replace(x, is.na(x), mean(x, na.rm = TRUE))
    ok <- vapply(df, is.numeric, logical(1))
    df[ok] <- lapply(df[ok], na.mean)
    df[fix(pr),"Precip"] <-  0
    df[fix(pr1),"Precip"] <-  200
    df[fix(rg),"Rg_f"] <- 59
    df[fix(tm),"Ta_f"] <- 49

    if(save && is.character(file_meteo)){
      utils::write.table(df,file_meteo,row.names=F,col.names=T,quote=FALSE,sep="\t")
      message(file_meteo, " saved!")
    }
  }
  if (plot) {
    if (!is.character(file_meteo)) stop("plot = TRUE requires file_meteo to be a path to a meteo file")
    R3DFEM::plot_meteo_3DFEM(file_meteo,
                             daterange = c(sprintf("%04d-%02d-%02d", meteo$Year[1], meteo$Month[1], meteo$n_days[1]),
                                           sprintf("%04d-%02d-%02d", meteo$Year[nrow(meteo)], meteo$Month[nrow(meteo)], meteo$n_days[nrow(meteo)])),...)
  }
  if(correct){
    return(df)
  }else {
    return(invisible(meteo))
  }
}
